var COM = {"0": "<p>Certo. Art. 207.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Certo. Art. 208.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Errado. Art. 209: regra é a vedação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Certo. Art. 210, parágrafo único.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Errado. Art. 211 veda o crédito.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Errado. Art. 212, § 1º: não é contribuinte.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Certo. Art. 212, § 3º, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Certo. Art. 212, § 3º, II, g.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Errado. Não ficam sujeitas à incidência (art. 213).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Certo. Art. 213, § 3º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Errado. São excluídos IBS, CBS e ISS.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Certo. Art. 214, § 1º, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Errado. Normas gerais, salvo as operações de crédito (art. 214, § 2º).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Certo. Art. 215.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Certo. Art. 214, § 5º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Errado. Revogado pela LC 227/2026.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Certo. Art. 218-A, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Certo. Art. 219, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Errado. § 7º: não ficam sujeitos.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Errado. Art. 219-A, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Certo. Parágrafo único do art. 219-A.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Certo. Art. 220.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Certo. Art. 222.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Certo. Art. 223, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "24": "<p>Errado. Art. 223, § 2º: não sofre incidência nem dá crédito.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "25": "<p>Certo. Arts. 223, § 3º; 224, § 1º; 225, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "26": "<p>Errado. Art. 226 veda.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "27": "<p>Certo. Art. 225, I, b.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "28": "<p>Certo. Art. 228.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "29": "<p>Certo. Art. 228, § 1º, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "30": "<p>Certo. Art. 229.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "31": "<p>Certo. Art. 229, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "32": "<p>Errado. Art. 231: a mesma alíquota.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "33": "<p>Certo. Art. 232, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "34": "<p>Certo. Art. 232, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "35": "<p>Errado. Art. 232, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
